{
  "name": "opencode-pulselens",
  "version": "0.1.1",
  "description": "Live token speed metrics for the OpenCode TUI: tok/s, TTFT, TPOT and more",
  "type": "module",
  "license": "MIT",
  "author": "onevent",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Oniokey/PulseLens.git"
  },
  "homepage": "https://github.com/Oniokey/PulseLens",
  "bugs": {
    "url": "https://github.com/Oniokey/PulseLens/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "tokens",
    "ttft",
    "tpot",
    "performance"
  ],
  "exports": {
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "engines": {
    "opencode": ">=1.18.0"
  },
  "scripts": {
    "build": "bun run scripts/build.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "prepublishOnly": "node scripts/prepublish-check.mjs"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0",
    "@opentui/core": ">=0.5.0",
    "@opentui/solid": ">=0.5.0",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.25",
    "@opencode-ai/sdk": "1.18.25",
    "@opentui/core": "0.5.11",
    "@opentui/solid": "0.5.11",
    "@types/bun": "1.4.2",
    "solid-js": "1.9.12",
    "typescript": "5.9.3"
  }
}
